def backfill_opening_balances(apps, schema_editor):
    Tank = apps.get_model("fuel", "Tank")
    InventoryLedger = apps.get_model("fuel", "InventoryLedger")
    database = schema_editor.connection.alias
    tanks = (
        Tank.objects.using(database)
        .select_related("station")
        .filter(current_stock_litres__gt=0)
        .iterator()
    )
    for tank in tanks:
        entry = InventoryLedger.objects.using(database).create(
            tank_id=tank.pk,
            transaction_type="opening",
            quantity_delta=tank.current_stock_litres,
            recorded_by_id=tank.station.owner_id,
            notes="Opening balance carried forward from tank setup.",
        )
        InventoryLedger.objects.using(database).filter(pk=entry.pk).update(
            created_at=tank.created_at
        )


